structs.Command:
typedef struct Command
{
    char key;
    char *name;
    char *command;
    struct Command *children;
    struct Command *next;
} Command;

functions.NewCommand:
Command *NewCommand(char key, char *name, char *command)
{
    Command *cmd = (Command *)calloc(1, sizeof(Command));
    cmd->key = key;
    cmd->name = name;
    cmd->command = command;
    return cmd;
}

functions.CommandRun:
int CommandRun(Command *c)
{
    if (c != ((void *)0) && c->command != ((void *)0))
        return fprintf(stdout, "%s", c->command);
    return 0;
}

functions.CommandAddChild:
void CommandAddChild(Command *c, Command *child)
{
    if (c->children == ((void *)0))
    {
        c->children = child;
        return;
    }
    if (c->children->key > child->key)
    {
        child->next = c->children;
        c->children = child;
        return;
    }
    Command *lastChild = c->children;
    while (lastChild->next != ((void *)0) && lastChild->next->key <= child->key)
    {
        lastChild = lastChild->next;
    }
    child->next = lastChild->next;
    lastChild->next = child;
}

functions.FindCommand:
Command *FindCommand(Command *c, char key)
{
    Command *child = c->children;
    while (child != ((void *)0) && child->key != key)
        child = child->next;
    return child;
}

functions.TreeAddCommand:
void TreeAddCommand(Command *tree, char *keys, char *name, char *command)
{
    Command *c = FindCommand(tree, *keys);
    if (*(keys + 1) == 0)
    {
        if (c == ((void *)0))
        {
            CommandAddChild(tree, NewCommand(*keys, name, command));
        }
        else
        {
            c->name = name;
            c->command = command;
        }
        return;
    }
    if (c == ((void *)0))
    {
        c = NewCommand(*keys, "unnamed", 0);
        CommandAddChild(tree, c);
    }
    TreeAddCommand(c, keys + 1, name, command);
}

functions.PrintCommand:
int PrintCommand(Command *c)
{
    struct winsize terminal;
    ioctl(2, 0x5413, &terminal);
    int width = terminal.ws_col;
    int lines = 0;
    if (c->name)
    {
        fprintf(stderr, "%s%s:%s\n", "\033[0;34m", c->name, "\033[0m");
        lines++;
    }
    int maxLineWidth = 0;
    Command *child = c->children;
    while (child)
    {
        int lineWidth = strlen(child->name);
        if (lineWidth > maxLineWidth)
            maxLineWidth = lineWidth;
        child = child->next;
    }
    maxLineWidth += 5;
    if (maxLineWidth > width)
        maxLineWidth = width;
    int itemsPerRow = width / (maxLineWidth + 5);
    child = c->children;
    int currentItem = 0;
    while (child)
    {
        currentItem++;
        if (child->children != 0)
        {
            fprintf(stderr, "%s%c%s %s➔%s %s+%-*s%s", "\033[0;33m", child->key, "\033[0m", "\033[0;35m", "\033[0m",
                    "\033[0;34m", maxLineWidth, child->name, "\033[0m");
        }
        else
        {
            fprintf(stderr, "%s%c%s %s➔%s  %-*s", "\033[0;33m", child->key, "\033[0m", "\033[0;35m", "\033[0m",
                    maxLineWidth, child->name);
        }
        if (currentItem % itemsPerRow == 0)
        {
            fprintf(stderr, "\n");
            lines++;
        }
        child = child->next;
    }
    fprintf(stderr, "\n");
    lines++;
    return lines;
}

functions.getch:
char getch(void)
{
    struct termios old = {0};
    if (tcgetattr(0, &old) < 0)
        perror("tcsetattr()");
    tcflag_t oldflags = old.c_lflag;
    old.c_lflag &= ~0000002;
    old.c_lflag &= ~0000010;
    old.c_cc[6] = 1;
    old.c_cc[5] = 0;
    if (tcsetattr(0, 0, &old) < 0)
        perror("tcsetattr ICANON");
    char buf = 0;
    if (read(0, &buf, 1) < 0)
        perror("read()");
    old.c_lflag = oldflags;
    if (tcsetattr(0, 1, &old) < 0)
        perror("tcsetattr ~ICANON");
    return (buf);
}

functions.ReadFile:
char *ReadFile(char *file)
{
    FILE *f = fopen(file, "r");
    if (f == ((void *)0))
    {
        perror("Failed to open file");
        exit(1);
    }
    fseek(f, 0, 2);
    long fileSize = ftell(f);
    rewind(f);
    char *content = (char *)calloc(fileSize + 1, sizeof(char));
    fread(content, fileSize, 1, f);
    fclose(f);
    return content;
}

functions.ReadField:
char *ReadField(char **file, char *field)
{
    char *key = *file;
    while (**file != ',' && **file != '\n' && **file != 0)
        (*file)++;
    if (**file != ',')
    {
        fprintf(stderr, "Found incorrect end after %s, found: %c", field, **file);
        exit(1);
    }
    **file = 0;
    (*file)++;
    return key;
}

functions.ReadUntilEOL:
char *ReadUntilEOL(char **file)
{
    char *s = *file;
    while (**file != '\n' && **file != 0)
        (*file)++;
    if (**file == '\n')
    {
        **file = 0;
        (*file)++;
    }
    return s;
}

functions.ReadLine:
void ReadLine(Command *c, char **file)
{
    char *key = ReadField(file, "key");
    char *name = ReadField(file, "name");
    char *command = ReadUntilEOL(file);
    TreeAddCommand(c, key, name, command);
}

functions.ClearLines:
void ClearLines(int count)
{
    setbuf(stdout, ((void *)0));
    for (int i = 0; i < count; i++)
        fprintf(stderr, "\033[A\r\33[2K");
}

functions.LoadFile:
void LoadFile(Command *c, char *file)
{
    char *content = ReadFile(file);
    while (*content != 0)
        ReadLine(c, &content);
}

functions.Start:
void Start(Command *c)
{
    while (c != ((void *)0) && c->children != ((void *)0))
    {
        int lastPrintedLines = PrintCommand(c);
        c = FindCommand(c, getch());
        ClearLines(lastPrintedLines);
        if (CommandRun(c) > 0)
        {
            return;
        };
    }
}
